{
  "findings": [
    {
      "check_id": "CKV_GCP_106",
      "title": "Unrestricted HTTP ingress",
      "resource": "google_compute_firewall.allow_http",
      "severity": "MEDIUM",
      "explanation": "The firewall permits TCP port 80 from 0.0.0.0/0, exposing unencrypted HTTP service traffic to the entire internet."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http\" {\n  name    = \"digital-library-content-management-platform-firewall-http\"\n  network = google_compute_network.digital_library_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"443\"]\n  }\n  source_ranges = [\"0.0.0.0/0\"]\n  target_tags   = [\"http-server\"]\n}\n",
  "fix_summary": "Removed public ingress on unencrypted HTTP port 80 while retaining the existing HTTPS port 443 access."
}
